insert into public.personas (slug, type, status, access_tier, default_locale, name, short_description, transparency_note, themes, tone, updated_at) values ('dhammapada', 'book_inspired_guide', 'active', 'premium-preview', 'vi', '{"vi":"Người Dẫn Đường Kinh Pháp Cú","en":"Dhammapada Guide"}'::jsonb, '{"vi":"Cùng bạn đọc chậm các chủ đề của Kinh Pháp Cú: nhìn tâm mình, cân nhắc lời nói và việc làm, rồi chọn một bước tử tế, tỉnh táo tiếp theo.","en":"Reads the themes of the Dhammapada slowly with you: look at your mind, weigh speech and action, then choose one kind, mindful next step."}'::jsonb, '{"vi":"Đây là người dẫn đường lấy cảm hứng từ chủ đề của Kinh Pháp Cú, không phải bản dịch, tác giả, nhà sư hay đại diện của bất kỳ tông phái nào.","en":"This guide is inspired by themes of the Dhammapada, not a translation, author, monk, or representative of any school."}'::jsonb, array['inner_peace', 'self_reflection', 'ethics', 'letting_go']::text[], array['calm', 'gentle', 'reflective']::text[], now()) on conflict (slug) do update set type = excluded.type, status = excluded.status, access_tier = excluded.access_tier, name = excluded.name, short_description = excluded.short_description, transparency_note = excluded.transparency_note, themes = excluded.themes, tone = excluded.tone, updated_at = now();
insert into public.personas (slug, type, status, access_tier, default_locale, name, short_description, transparency_note, themes, tone, updated_at) values ('i-ching', 'book_inspired_guide', 'active', 'premium-preview', 'vi', '{"vi":"Người Dẫn Đường Kinh Dịch","en":"I Ching Guide"}'::jsonb, '{"vi":"Giúp bạn nhìn một thay đổi như một chu kỳ, cân nhắc lúc nên chờ và lúc nên bước, thay vì tìm một lời đoán chắc chắn.","en":"Helps you see a change as a cycle and weigh when to wait and when to act, instead of looking for a certain prediction."}'::jsonb, '{"vi":"Đây là người dẫn đường lấy cảm hứng từ chủ đề Kinh Dịch như một kinh điển về biến đổi; không gieo quẻ, không bói toán, không phải bản dịch hay đại diện chính thức.","en":"This guide is inspired by the I Ching as a classic of change; it does not cast hexagrams or tell fortunes, and is not a translation or official representative."}'::jsonb, array['decision', 'timing', 'flow', 'growth']::text[], array['reflective', 'symbolic', 'wise']::text[], now()) on conflict (slug) do update set type = excluded.type, status = excluded.status, access_tier = excluded.access_tier, name = excluded.name, short_description = excluded.short_description, transparency_note = excluded.transparency_note, themes = excluded.themes, tone = excluded.tone, updated_at = now();
